// js/roles/master_reportes.js — Reportes y contabilidad profesional AURA

const AURA_LOGO_B64 = "";

window.render_master_reportes = async function(el, p) {

  // ── FUNCIONES GLOBALES (antes del render) ──
  window.repSetRango = function(dias) {
    const hasta = new Date();
    const desde = new Date();
    if (dias > 0) desde.setDate(desde.getDate() - dias);
    else { desde.setDate(1); } // mes actual
    document.getElementById('repDesde').value = desde.toISOString().split('T')[0];
    document.getElementById('repHasta').value = hasta.toISOString().split('T')[0];
  };

  window.repSetFiltro = function(id) {
    ['repFiltroTodos','repFiltroStreamers','repFiltroAgencias'].forEach(f => {
      const btn = document.getElementById(f);
      if (!btn) return;
      const active = f === id;
      btn.style.background = active?'rgba(212,175,55,0.1)':'rgba(255,255,255,0.04)';
      btn.style.borderColor = active?'rgba(212,175,55,0.4)':'rgba(255,255,255,0.08)';
      btn.style.color = active?'var(--gold)':'rgba(255,255,255,0.7)';
    });
    window._repFiltroActual = id;
  };
  window._repFiltroActual = 'repFiltroTodos';

  el.innerHTML = `
    <div class="dash-welcome aura-fade-up">
      <h1>📊 <span>Contabilidad</span></h1>
      <p>Reportes financieros de la plataforma AURA</p>
    </div>

    <div class="card" style="margin-bottom:16px">
      <div class="section-title" style="margin-bottom:14px">📅 Rango de fechas</div>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:12px">
        <div>
          <div style="font-size:11px;color:var(--mu);margin-bottom:6px">Desde</div>
          <input type="date" id="repDesde" style="width:100%;background:rgba(255,255,255,0.05);border:1px solid rgba(255,255,255,0.1);border-radius:10px;padding:10px 12px;color:#fff;font-size:13px;outline:none;box-sizing:border-box">
        </div>
        <div>
          <div style="font-size:11px;color:var(--mu);margin-bottom:6px">Hasta</div>
          <input type="date" id="repHasta" style="width:100%;background:rgba(255,255,255,0.05);border:1px solid rgba(255,255,255,0.1);border-radius:10px;padding:10px 12px;color:#fff;font-size:13px;outline:none;box-sizing:border-box">
        </div>
      </div>
      <div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:12px">
        ${[{l:'Hoy',d:0},{l:'7 días',d:7},{l:'15 días',d:15},{l:'Mes actual',d:30},{l:'Todo',d:365}].map(r=>`
          <button onclick="repSetRango(${r.d})" style="padding:7px 14px;border-radius:20px;background:rgba(255,255,255,0.04);border:1px solid rgba(255,255,255,0.08);color:rgba(255,255,255,0.7);font-size:12px;cursor:pointer">${r.l}</button>
        `).join('')}
      </div>
      <div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:14px">
        <span style="font-size:12px;color:var(--mu);align-self:center">Ver:</span>
        <button id="repFiltroTodos" onclick="repSetFiltro('repFiltroTodos')" style="padding:7px 14px;border-radius:20px;background:rgba(212,175,55,0.1);border:1px solid rgba(212,175,55,0.4);color:var(--gold);font-size:12px;cursor:pointer">Todos</button>
        <button id="repFiltroStreamers" onclick="repSetFiltro('repFiltroStreamers')" style="padding:7px 14px;border-radius:20px;background:rgba(255,255,255,0.04);border:1px solid rgba(255,255,255,0.08);color:rgba(255,255,255,0.7);font-size:12px;cursor:pointer">Solo streamers</button>
        <button id="repFiltroAgencias" onclick="repSetFiltro('repFiltroAgencias')" style="padding:7px 14px;border-radius:20px;background:rgba(255,255,255,0.04);border:1px solid rgba(255,255,255,0.08);color:rgba(255,255,255,0.7);font-size:12px;cursor:pointer">Solo agencias</button>
      </div>
      <button onclick="repGenerar()" class="btn-primary" style="width:100%;padding:14px">
        🔍 Generar reporte
      </button>
    </div>

    <div id="repResultado"></div>
  `;

  window.repSetRango(30);

  // ── GENERAR REPORTE ──
  window.repGenerar = async function() {
    const desdeStr = document.getElementById('repDesde')?.value;
    const hastaStr = document.getElementById('repHasta')?.value;
    if (!desdeStr || !hastaStr) { toast('Selecciona el rango de fechas','error'); return; }

    const desde = new Date(desdeStr + 'T00:00:00');
    const hasta = new Date(hastaStr + 'T23:59:59');

    const cont = document.getElementById('repResultado');
    if (cont) cont.innerHTML = `<div style="text-align:center;padding:40px;color:var(--mu)">
      <div style="font-size:40px;margin-bottom:14px;animation:pulse 1s infinite">⏳</div>
      Generando reporte...
    </div>`;

    try {
      const [usuarios, historial, retiros] = await Promise.all([
        window.fsGetAll('usuarios'),
        window.fsGetAll('historial_estrellas').catch(()=>[]),
        window.fsGetAll('retiros').catch(()=>[]),
      ]);

      // Filtrar por fechas
      const hist = (historial||[]).filter(h => {
        const f = h.createdAt?.toDate?.() || new Date(h.createdAt||0);
        return f >= desde && f <= hasta;
      });

      const streamers = usuarios.filter(u=>u.rol==='streamer');
      const agencias = usuarios.filter(u=>u.rol==='agencia');

      // Ganancias por streamer
      const gStr = {};
      streamers.forEach(s => { gStr[s.id] = {bruto:0,str_part:0,ag_part:0,master_part:0,tx:0}; });
      hist.forEach(h => {
        if (!h.uid_to || !gStr[h.uid_to]) return;
        gStr[h.uid_to].bruto     += h.cantidad||0;
        gStr[h.uid_to].str_part  += h.dist_streamer||0;
        gStr[h.uid_to].ag_part   += h.dist_agencia||0;
        gStr[h.uid_to].master_part += h.dist_master||0;
        gStr[h.uid_to].tx++;
      });

      // Ganancias por agencia
      const gAg = {};
      agencias.forEach(a => { gAg[a.id] = {str_ingresos:0, ag_part:0, master_part:0, streamers:[]}; });
      streamers.forEach(s => {
        if (!s.agencia_uid || !gAg[s.agencia_uid]) return;
        const g = gStr[s.id]||{};
        gAg[s.agencia_uid].str_ingresos += g.str_part||0;
        gAg[s.agencia_uid].ag_part += g.ag_part||0;
        gAg[s.agencia_uid].master_part += g.master_part||0;
        gAg[s.agencia_uid].streamers.push({
          uid:s.id, nick:s.nick||s.nombre, nivel:s.nivel||'bronce',
          ingresos:g.str_part||0, ag:g.ag_part||0, master:g.master_part||0
        });
      });

      // Totales globales
      const totBruto = Object.values(gStr).reduce((a,g)=>a+g.bruto,0);
      const totStr   = Object.values(gStr).reduce((a,g)=>a+g.str_part,0);
      const totAg    = Object.values(gStr).reduce((a,g)=>a+g.ag_part,0);
      const totMaster= Object.values(gStr).reduce((a,g)=>a+g.master_part,0);

      // Por nivel
      const porNivel = {};
      ['bronce','plata','oro','diamante'].forEach(n=>{ porNivel[n]={count:0,bruto:0,master:0,str:0}; });
      streamers.forEach(s=>{
        const nv = s.nivel||'bronce';
        if (!porNivel[nv]) return;
        const g = gStr[s.id]||{};
        porNivel[nv].count++;
        porNivel[nv].bruto += g.bruto||0;
        porNivel[nv].master += g.master_part||0;
        porNivel[nv].str += g.str_part||0;
      });

      const retirosP = (retiros||[]).filter(r=>{
        const f = r.createdAt?.toDate?.() || new Date(r.createdAt||0);
        return f >= desde && f <= hasta;
      });

      // Guardar para PDF
      window._repData = { desdeStr, hastaStr, totBruto, totStr, totAg, totMaster,
        streamers, agencias, gStr, gAg, porNivel, retirosP, hist, masterNick: p.nick||p.nombre };

      const filtro = window._repFiltroActual || 'repFiltroTodos';
      if (!document.getElementById('repResultado')) return;

      document.getElementById('repResultado').innerHTML = `
        <!-- HERO RESUMEN -->
        <div style="padding:20px;border-radius:16px;background:linear-gradient(135deg,#0d0d0d,#1a0800);border:1px solid rgba(212,175,55,0.3);margin-bottom:16px">
          <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:16px;flex-wrap:wrap;gap:10px">
            <div>
              <div style="font-family:'Cinzel',serif;font-size:18px;font-weight:800;color:var(--gold)">📊 Reporte AURA</div>
              <div style="font-size:11px;color:var(--mu);margin-top:2px">${desdeStr} → ${hastaStr} · ${hist.length} transacciones</div>
            </div>
            <button onclick="repImprimir()" style="display:flex;align-items:center;gap:8px;padding:10px 20px;border-radius:12px;background:linear-gradient(135deg,rgba(212,175,55,0.2),rgba(212,175,55,0.05));border:1px solid rgba(212,175,55,0.4);color:var(--gold);font-size:13px;font-weight:700;cursor:pointer;box-shadow:0 0 16px rgba(212,175,55,0.15)">
              🖨️ Imprimir / PDF
            </button>
          </div>
          <div style="display:grid;grid-template-columns:repeat(2,1fr);gap:10px">
            ${[
              {l:'Total Bruto',v:totBruto,c:'#fff'},
              {l:'AURA Plataforma',v:totMaster,c:'var(--gold)'},
              {l:'Streamers',v:totStr,c:'#22c55e'},
              {l:'Agencias',v:totAg,c:'#A78BFA'},
            ].map(s=>`
              <div style="padding:14px;background:rgba(0,0,0,0.4);border-radius:12px;border:1px solid rgba(255,255,255,0.05);text-align:center">
                <div style="font-size:10px;text-transform:uppercase;letter-spacing:2px;color:var(--mu);margin-bottom:6px">${s.l}</div>
                <div style="font-family:'Cinzel',serif;font-size:20px;font-weight:900;color:${s.c}">${s.v.toLocaleString()}⭐</div>
                <div style="font-size:11px;color:var(--mu);margin-top:2px">≈ $${(s.v/200).toFixed(2)} USD</div>
              </div>
            `).join('')}
          </div>
        </div>

        ${(filtro==='repFiltroTodos'||filtro==='repFiltroStreamers') ? `
        <!-- STREAMERS -->
        <div class="card" style="margin-bottom:14px">
          <div class="section-title" style="margin-bottom:12px">🎤 Desglose por Streamer</div>
          ${streamers.length===0?'<div style="text-align:center;padding:20px;color:var(--mu)">Sin streamers aún.</div>':
            streamers.sort((a,b)=>(gStr[b.id]?.bruto||0)-(gStr[a.id]?.bruto||0)).map(s=>{
              const g=gStr[s.id]||{bruto:0,str_part:0,ag_part:0,master_part:0,tx:0};
              const nv=window.getNivel?.(s.nivel||'bronce');
              return `
                <div style="border-radius:12px;background:rgba(255,255,255,0.02);border:1px solid rgba(255,255,255,0.04);margin-bottom:8px;overflow:hidden">
                  <div style="display:flex;align-items:center;gap:10px;padding:12px;cursor:pointer" onclick="repToggle('str_${s.id}')">
                    <div class="card-avatar" style="width:38px;height:38px;font-size:15px;flex-shrink:0">${(s.nick||s.nombre||'?')[0].toUpperCase()}</div>
                    <div style="flex:1;min-width:0">
                      <div style="font-weight:700;font-size:13px">@${s.nick||s.nombre} <span>${nv?.emoji||'🥉'}</span> <span style="font-size:10px;color:var(--mu)">${nv?.nombre||'Bronce'}</span></div>
                      <div style="font-size:10px;color:var(--mu)">${s.pais||'—'} · ${g.tx} transacciones · ${s.frecuencia_pago||'mensual'}</div>
                    </div>
                    <div style="text-align:right;flex-shrink:0">
                      <div style="font-weight:700;color:var(--gold)">${g.bruto.toLocaleString()}⭐</div>
                      <div style="font-size:10px;color:var(--mu)">$${(g.bruto/200).toFixed(2)}</div>
                    </div>
                    <span style="color:var(--mu);font-size:16px;flex-shrink:0" id="arr_str_${s.id}">›</span>
                  </div>
                  <div id="rep_str_${s.id}" style="display:none;padding:12px;background:rgba(0,0,0,0.3);border-top:1px solid rgba(255,255,255,0.04)">
                    <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:8px;font-size:12px;text-align:center">
                      <div style="padding:10px;background:rgba(34,197,94,0.08);border-radius:10px">
                        <div style="color:var(--mu);margin-bottom:4px">Streamer (${nv?.streamer||20}%)</div>
                        <div style="font-weight:700;color:#22c55e">${g.str_part.toLocaleString()}⭐</div>
                        <div style="color:var(--mu);font-size:10px">$${(g.str_part/200).toFixed(2)}</div>
                      </div>
                      <div style="padding:10px;background:rgba(167,139,250,0.08);border-radius:10px">
                        <div style="color:var(--mu);margin-bottom:4px">Agencia (${nv?.agencia||10}%)</div>
                        <div style="font-weight:700;color:#A78BFA">${g.ag_part.toLocaleString()}⭐</div>
                        <div style="color:var(--mu);font-size:10px">$${(g.ag_part/200).toFixed(2)}</div>
                      </div>
                      <div style="padding:10px;background:rgba(212,175,55,0.08);border-radius:10px">
                        <div style="color:var(--mu);margin-bottom:4px">AURA (${nv?.master||70}%)</div>
                        <div style="font-weight:700;color:var(--gold)">${g.master_part.toLocaleString()}⭐</div>
                        <div style="color:var(--mu);font-size:10px">$${(g.master_part/200).toFixed(2)}</div>
                      </div>
                    </div>
                  </div>
                </div>
              `;
            }).join('')
          }
        </div>` : ''}

        ${(filtro==='repFiltroTodos'||filtro==='repFiltroAgencias') ? `
        <!-- AGENCIAS -->
        <div class="card" style="margin-bottom:14px">
          <div class="section-title" style="margin-bottom:12px">🏢 Desglose por Agencia</div>
          ${agencias.length===0?'<div style="text-align:center;padding:20px;color:var(--mu)">Sin agencias aún.</div>':
            agencias.sort((a,b)=>(gAg[b.id]?.ag_part||0)-(gAg[a.id]?.ag_part||0)).map(a=>{
              const ga=gAg[a.id]||{str_ingresos:0,ag_part:0,master_part:0,streamers:[]};
              return `
                <div style="border-radius:12px;background:rgba(255,255,255,0.02);border:1px solid rgba(255,255,255,0.04);margin-bottom:8px;overflow:hidden">
                  <div style="display:flex;align-items:center;gap:10px;padding:12px;cursor:pointer" onclick="repToggle('ag_${a.id}')">
                    <div class="card-avatar" style="width:38px;height:38px;font-size:15px;background:rgba(167,139,250,0.15);border-color:rgba(167,139,250,0.3);flex-shrink:0">${(a.nick||a.nombre||'?')[0].toUpperCase()}</div>
                    <div style="flex:1;min-width:0">
                      <div style="font-weight:700;font-size:13px">@${a.nick||a.nombre}</div>
                      <div style="font-size:10px;color:var(--mu)">${ga.streamers.length} streamers</div>
                    </div>
                    <div style="text-align:right;flex-shrink:0">
                      <div style="font-weight:700;color:#A78BFA">${ga.ag_part.toLocaleString()}⭐</div>
                      <div style="font-size:10px;color:var(--mu)">$${(ga.ag_part/200).toFixed(2)}</div>
                    </div>
                    <span style="color:var(--mu);font-size:16px;flex-shrink:0" id="arr_ag_${a.id}">›</span>
                  </div>
                  <div id="rep_ag_${a.id}" style="display:none;padding:12px;background:rgba(0,0,0,0.3);border-top:1px solid rgba(255,255,255,0.04)">
                    ${ga.streamers.length===0?'<div style="color:var(--mu);text-align:center;font-size:12px">Sin actividad en este período</div>':
                      ga.streamers.map(s=>{
                        const nv=window.getNivel?.(s.nivel||'bronce');
                        return `
                          <div style="display:grid;grid-template-columns:1fr auto auto auto;gap:10px;padding:8px 0;border-bottom:1px solid rgba(255,255,255,0.04);font-size:12px;align-items:center">
                            <div><b>@${s.nick}</b> <span style="font-size:10px">${nv?.emoji||'🥉'}</span></div>
                            <div style="color:#22c55e;text-align:right">${s.ingresos.toLocaleString()}⭐<br><span style="color:var(--mu);font-size:10px">streamer</span></div>
                            <div style="color:#A78BFA;text-align:right">${s.ag.toLocaleString()}⭐<br><span style="color:var(--mu);font-size:10px">agencia</span></div>
                            <div style="color:var(--gold);text-align:right">${s.master.toLocaleString()}⭐<br><span style="color:var(--mu);font-size:10px">AURA</span></div>
                          </div>
                        `;
                      }).join('')
                    }
                    <div style="display:flex;justify-content:space-between;padding:10px 0 0;font-size:12px;font-weight:700">
                      <span>Total agencia</span>
                      <span style="color:#A78BFA">${ga.ag_part.toLocaleString()}⭐ · $${(ga.ag_part/200).toFixed(2)}</span>
                    </div>
                  </div>
                </div>
              `;
            }).join('')
          }
        </div>` : ''}

        <!-- DETALLE POR NIVEL -->
        <div class="card" style="margin-bottom:14px">
          <div class="section-title" style="margin-bottom:12px">🏆 Rendimiento por nivel</div>
          ${['bronce','plata','oro','diamante'].map(n=>{
            const nv=window.getNivel?.(n);
            const pn=porNivel[n]||{count:0,bruto:0,master:0,str:0};
            return `
              <div style="display:flex;align-items:center;gap:12px;padding:10px 0;border-bottom:1px solid rgba(255,255,255,0.04)">
                <span style="font-size:22px">${nv?.emoji||'🥉'}</span>
                <div style="flex:1">
                  <div style="font-weight:600;font-size:13px">${nv?.nombre||n} · ${pn.count} streamers</div>
                  <div style="font-size:10px;color:var(--mu)">${nv?.streamer}% streamer / ${nv?.agencia}% agencia / ${nv?.master}% AURA</div>
                </div>
                <div style="text-align:right">
                  <div style="font-weight:700;color:var(--gold);font-size:13px">${pn.bruto.toLocaleString()}⭐</div>
                  <div style="font-size:10px;color:var(--mu)">$${(pn.bruto/200).toFixed(2)}</div>
                </div>
              </div>
            `;
          }).join('')}
        </div>

        <!-- RETIROS -->
        <div class="card" style="margin-bottom:16px">
          <div class="section-title" style="margin-bottom:12px">💳 Retiros en el período</div>
          ${retirosP.length===0?'<div style="text-align:center;padding:16px;color:var(--mu)">Sin retiros en este período.</div>':
            retirosP.map(r=>`
              <div style="display:flex;align-items:center;justify-content:space-between;padding:10px 0;border-bottom:1px solid rgba(255,255,255,0.04);font-size:12px">
                <div>
                  <div style="font-weight:600">@${r.nick||'—'}</div>
                  <div style="color:var(--mu)">${r.metodo||'—'} · ${r.createdAt?.toDate?.()?.toLocaleDateString?.('es')||'Reciente'}</div>
                </div>
                <div style="text-align:right">
                  <div style="font-weight:700;color:var(--gold)">${r.monto_usd?'$'+r.monto_usd+' USD':(r.monto||0)+'★'}</div>
                  <span class="badge ${r.estado==='pagado'?'badge-green':r.estado==='rechazado'?'badge-red':'badge-orange'}" style="font-size:9px">${r.estado}</span>
                </div>
              </div>
            `).join('')
          }
        </div>

        <button onclick="repImprimir()" style="width:100%;padding:16px;border-radius:var(--r-lg);background:linear-gradient(135deg,rgba(212,175,55,0.15),rgba(212,175,55,0.03));border:1px solid rgba(212,175,55,0.35);color:var(--gold);font-size:14px;font-weight:700;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:10px;margin-bottom:20px;box-shadow:0 0 20px rgba(212,175,55,0.1)">
          🖨️ Imprimir reporte / Descargar PDF
        </button>
      `;

      window.repToggle = function(id) {
        const d = document.getElementById('rep_'+id);
        const a = document.getElementById('arr_'+id);
        if (!d) return;
        const open = d.style.display !== 'none';
        d.style.display = open ? 'none' : 'block';
        if (a) a.textContent = open ? '›' : '⌄';
      };

    } catch(e) {
      const c = document.getElementById('repResultado');
      if (c) c.innerHTML = `<div class="card" style="text-align:center;padding:20px;color:var(--mu)">Error: ${e.message}</div>`;
      console.error(e);
    }
  };

  // ── PDF PROFESIONAL ESTILO AURA ──
  window.repImprimir = function() {
    const d = window._repData;
    if (!d) { toast('Primero genera el reporte','error'); return; }

    const usd = v => '$' + (v/200).toFixed(2);
    const fmt = v => v.toLocaleString();

    const html = `<!DOCTYPE html>
<html lang="es">
<head>
<meta charset="UTF-8">
<title>Reporte Contable AURA ${d.desdeStr} - ${d.hastaStr}</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Cinzel:wght@400;700;900&family=Outfit:wght@300;400;600;700&display=swap');
  * { box-sizing:border-box; margin:0; padding:0; }
  body { font-family:'Outfit',Arial,sans-serif; color:#e8dcc8; background:#0d0d0d; font-size:12px; }

  /* HEADER */
  .header { background:linear-gradient(135deg,#050505 0%,#120e05 50%,#050505 100%); padding:24px 32px; display:flex; align-items:center; justify-content:space-between; position:relative; overflow:hidden; border-bottom:1px solid rgba(212,175,55,0.3); }
  .header::before { content:''; position:absolute; inset:0; background:radial-gradient(ellipse at 20% 50%,rgba(212,175,55,0.12),transparent 60%); pointer-events:none; }
  .header-logo { display:flex; align-items:center; gap:16px; }
  .header-logo img { height:56px; object-fit:contain; }
  .header-brand .brand-name { font-family:'Cinzel',serif; font-size:28px; font-weight:900; color:#D4AF37; letter-spacing:4px; }
  .header-brand .brand-tagline { font-size:10px; letter-spacing:4px; color:rgba(212,175,55,0.5); text-transform:uppercase; margin-top:2px; }
  .header-right { text-align:right; }
  .header-right .rep-title { font-family:'Cinzel',serif; font-size:18px; font-weight:700; color:#D4AF37; letter-spacing:2px; }
  .header-right .rep-sub { font-size:10px; color:rgba(212,175,55,0.5); letter-spacing:2px; text-transform:uppercase; margin-top:4px; }
  .header-right .rep-periodo { margin-top:8px; background:rgba(212,175,55,0.1); border:1px solid rgba(212,175,55,0.4); border-radius:6px; padding:5px 12px; display:inline-block; color:#D4AF37; font-size:11px; font-weight:600; }

  /* DIVIDERS */
  .gold-bar { height:2px; background:linear-gradient(90deg,transparent,#CC0000,#D4AF37,#CC0000,transparent); }
  .red-bar  { height:1px; background:linear-gradient(90deg,transparent,#CC0000,transparent); margin:0; }

  /* BODY */
  .body { padding:24px 32px; background:#0d0d0d; }

  /* SECTION TITLES */
  .section-title { font-family:'Cinzel',serif; font-size:12px; font-weight:700; color:#D4AF37; text-transform:uppercase; letter-spacing:2px; margin:20px 0 10px; padding-bottom:6px; border-bottom:2px solid #CC0000; display:flex; align-items:center; gap:8px; }

  /* SUMMARY GRID */
  .summary-grid { display:grid; grid-template-columns:repeat(4,1fr); gap:12px; margin-bottom:20px; }
  .summary-card { border:1px solid rgba(212,175,55,0.25); border-radius:10px; padding:14px; text-align:center; background:linear-gradient(135deg,#151005,#0d0d0d); }
  .summary-card .sc-icon { font-size:22px; margin-bottom:6px; }
  .summary-card .sc-label { font-size:9px; text-transform:uppercase; letter-spacing:2px; color:rgba(212,175,55,0.6); margin-bottom:6px; font-weight:600; }
  .summary-card .sc-value { font-family:'Cinzel',serif; font-size:18px; font-weight:900; color:#e8dcc8; }
  .summary-card .sc-sub { font-size:10px; color:rgba(255,255,255,0.35); margin-top:2px; }
  .summary-card.gold-card { background:linear-gradient(135deg,#1a0800,#0d0d0d); border-color:#D4AF37; box-shadow:0 0 20px rgba(212,175,55,0.1); }
  .summary-card.gold-card .sc-label { color:rgba(212,175,55,0.7); }
  .summary-card.gold-card .sc-value { color:#D4AF37; }
  .summary-card.gold-card .sc-sub { color:rgba(212,175,55,0.4); }

  /* TABLES */
  table { width:100%; border-collapse:collapse; margin-bottom:20px; font-size:11.5px; }
  thead tr { background:linear-gradient(135deg,#1a0000,#0d0d0d); border-bottom:2px solid #CC0000; }
  thead th { padding:10px 8px; color:#D4AF37; font-family:'Cinzel',serif; font-size:9px; font-weight:700; text-transform:uppercase; letter-spacing:1px; text-align:left; border:1px solid rgba(204,0,0,0.3); }
  tbody tr { border-bottom:1px solid rgba(255,255,255,0.05); }
  tbody tr:nth-child(even) { background:rgba(255,255,255,0.02); }
  tbody tr:hover { background:rgba(212,175,55,0.04); }
  tbody td { padding:9px 8px; color:#d4c9b0; border-left:1px solid rgba(204,0,0,0.15); border-right:1px solid rgba(204,0,0,0.15); vertical-align:middle; }
  tfoot tr { background:linear-gradient(135deg,#1a0000,#0d0d0d); border-top:2px solid #CC0000; }
  tfoot td { padding:10px 8px; color:#D4AF37; font-family:'Cinzel',serif; font-size:10px; font-weight:700; letter-spacing:1px; border:1px solid rgba(204,0,0,0.3); }

  /* BADGES */
  .nivel-badge { display:inline-flex; align-items:center; gap:4px; padding:3px 9px; border-radius:20px; font-size:9px; font-weight:700; text-transform:uppercase; letter-spacing:1px; }
  .badge-bronce { background:rgba(205,127,50,0.15); color:#cd7f32; border:1px solid rgba(205,127,50,0.5); }
  .badge-plata  { background:rgba(192,192,192,0.1); color:#aaa; border:1px solid rgba(192,192,192,0.4); }
  .badge-oro    { background:rgba(212,175,55,0.15); color:#D4AF37; border:1px solid rgba(212,175,55,0.5); }
  .badge-diamante { background:rgba(159,216,255,0.15); color:#9FD8FF; border:1px solid rgba(159,216,255,0.5); }
  .estado-pagado   { color:#22c55e; font-weight:700; }
  .estado-pendiente { color:#f59e0b; font-weight:700; }
  .estado-rechazado { color:#ef4444; font-weight:700; }

  .nivel-row td:first-child { font-weight:700; }
  .green  { color:#4ade80; font-weight:700; }
  .purple { color:#a78bfa; font-weight:700; }
  .gold-text { color:#D4AF37; font-weight:700; }
  .red-text { color:#f87171; font-weight:700; }
  b { color:#fff; }

  /* TWO COLS */
  .two-cols { display:grid; grid-template-columns:1fr 1fr; gap:16px; margin-bottom:20px; }

  /* FOOTER */
  .footer { background:linear-gradient(135deg,#050505,#120e05); padding:18px 32px; display:flex; align-items:center; justify-content:space-between; margin-top:0; border-top:1px solid rgba(204,0,0,0.3); }
  .footer-logo { display:flex; align-items:center; gap:10px; }
  .footer-logo img { height:32px; opacity:0.7; }
  .footer-brand { font-family:'Cinzel',serif; font-size:14px; color:rgba(212,175,55,0.6); letter-spacing:3px; }
  .footer-notes { font-size:10px; color:rgba(212,175,55,0.4); }
  .footer-notes div { margin-bottom:2px; }
  .footer-right { text-align:right; }
  .footer-right .gen-by { font-size:10px; color:rgba(212,175,55,0.4); text-transform:uppercase; letter-spacing:1px; }
  .footer-right .gen-name { font-family:'Cinzel',serif; font-size:13px; color:#D4AF37; font-weight:700; margin-top:4px; }
  .footer-right .gen-date { font-size:10px; color:rgba(212,175,55,0.4); margin-top:2px; }

  .print-btn { display:block; text-align:center; margin:20px auto; padding:12px 32px; background:linear-gradient(135deg,#CC0000,#8B0000); color:#fff; border:none; border-radius:8px; font-family:'Cinzel',serif; font-size:14px; font-weight:700; cursor:pointer; letter-spacing:2px; box-shadow:0 0 20px rgba(204,0,0,0.4); }
  @media print { .print-btn { display:none; } body { background:#0d0d0d !important; -webkit-print-color-adjust:exact; print-color-adjust:exact; } }
</style>
</head>
<body>

<button class="print-btn" onclick="window.print()">🖨️ IMPRIMIR / GUARDAR PDF</button>

<!-- HEADER -->
<div class="header">
  <div class="header-logo">
    <img src="data:image/png;base64,${AURA_LOGO_B64}" alt="AURA">
    <div class="header-brand">
      <div class="brand-name">AURA</div>
      <div class="brand-tagline">Live Your Aura</div>
    </div>
  </div>
  <div class="header-right">
    <div class="rep-title">REPORTE CONTABLE GENERAL</div>
    <div class="rep-sub">Sistema de Contabilidad AURA</div>
    <div class="rep-periodo">PERÍODO: ${d.desdeStr} → ${d.hastaStr}</div>
  </div>
</div>
<div class="gold-bar"></div>

<div class="body">

  <!-- RESUMEN GENERAL -->
  <div class="section-title">📊 Resumen General</div>
  <div class="summary-grid">
    <div class="summary-card">
      <div class="sc-icon">🏢</div>
      <div class="sc-label">Total Ingresos<br>Agencias</div>
      <div class="sc-value">${usd(d.totAg)}</div>
      <div class="sc-sub">${fmt(d.totAg)} ⭐</div>
    </div>
    <div class="summary-card">
      <div class="sc-icon">🎤</div>
      <div class="sc-label">Total Ingresos<br>Streamers</div>
      <div class="sc-value">${usd(d.totStr)}</div>
      <div class="sc-sub">${fmt(d.totStr)} ⭐</div>
    </div>
    <div class="summary-card">
      <div class="sc-icon">👑</div>
      <div class="sc-label">Total Comisiones<br>AURA Plataforma</div>
      <div class="sc-value">${usd(d.totMaster)}</div>
      <div class="sc-sub">${fmt(d.totMaster)} ⭐</div>
    </div>
    <div class="summary-card gold-card">
      <div class="sc-icon">💰</div>
      <div class="sc-label">Total General<br>Ingresos</div>
      <div class="sc-value">${usd(d.totBruto)}</div>
      <div class="sc-sub">${fmt(d.totBruto)} ⭐</div>
    </div>
  </div>

  <!-- RESUMEN POR AGENCIAS -->
  ${d.agencias.length > 0 ? `
  <div class="section-title">🏢 Resumen por Agencias</div>
  <table>
    <thead><tr>
      <th>Nombre</th><th>Ingresos Agencia</th><th>Ingresos Streamers</th>
      <th>Comisión Ag. (AURA)</th><th>Comisión Str. (AURA)</th>
      <th>Total AURA</th><th>Total General</th>
    </tr></thead>
    <tbody>
      ${d.agencias.sort((a,b)=>(d.gAg[b.id]?.ag_part||0)-(d.gAg[a.id]?.ag_part||0)).map(a=>{
        const ga = d.gAg[a.id]||{str_ingresos:0,ag_part:0,master_part:0};
        const masterDeAg = ga.master_part;
        const totalAura = ga.ag_part * 0.05 + masterDeAg; // pequeña comisión sobre agencias
        return `<tr>
          <td><b>@${a.nick||a.nombre}</b></td>
          <td class="green">${usd(ga.ag_part)}</td>
          <td class="green">${usd(ga.str_ingresos)}</td>
          <td>${usd(ga.ag_part*0.05)}</td>
          <td>${usd(masterDeAg*0.1)}</td>
          <td class="gold-text">${usd(totalAura)}</td>
          <td><b>${usd(ga.ag_part+ga.str_ingresos)}</b></td>
        </tr>`;
      }).join('')}
    </tbody>
    <tfoot><tr>
      <td>TOTALES GENERALES</td>
      <td>${usd(d.totAg)}</td>
      <td>${usd(d.totStr)}</td>
      <td>—</td><td>—</td>
      <td>${usd(d.totMaster)}</td>
      <td>${usd(d.totBruto)}</td>
    </tr></tfoot>
  </table>` : ''}

  <div class="two-cols">
    <!-- DETALLE POR NIVELES -->
    <div>
      <div class="section-title">🏆 Detalle por Niveles</div>
      <table>
        <thead><tr><th>Nivel</th><th>Streamers</th><th>Ingresos</th><th>AURA</th><th>% Prom.</th><th>Ganancia Str.</th></tr></thead>
        <tbody>
          ${['bronce','plata','oro','diamante'].map(n=>{
            const nv=window.getNivel?.(n);
            const pn=d.porNivel[n]||{count:0,bruto:0,master:0,str:0};
            const badgeClass = 'badge-'+n;
            return `<tr class="nivel-row">
              <td><span class="nivel-badge ${badgeClass}">${nv?.emoji||''} ${nv?.nombre||n}</span></td>
              <td style="text-align:center">${pn.count}</td>
              <td class="gold-text">${usd(pn.bruto)}</td>
              <td>${usd(pn.master)}</td>
              <td>${nv?.master||70}% - ${nv?.master-5||65}%</td>
              <td class="green">${usd(pn.str)}</td>
            </tr>`;
          }).join('')}
        </tbody>
        <tfoot><tr>
          <td>TOTALES</td>
          <td style="text-align:center">${d.streamers.length}</td>
          <td>${usd(d.totBruto)}</td>
          <td>${usd(d.totMaster)}</td>
          <td>—</td>
          <td>${usd(d.totStr)}</td>
        </tr></tfoot>
      </table>
    </div>

    <!-- DETALLE AGENCIA-STREAMERS (primera agencia) -->
    ${d.agencias.length > 0 ? `
    <div>
      <div class="section-title">🏢 Agencia · Streamers</div>
      <table>
        <thead><tr><th>Streamer</th><th>Nivel</th><th>%</th><th>Ingresos</th><th>Comisión AURA</th><th>Ganancia Str.</th></tr></thead>
        <tbody>
          ${(d.gAg[d.agencias[0].id]?.streamers||[]).map(s=>{
            const nv=window.getNivel?.(s.nivel||'bronce');
            return `<tr>
              <td><b>@${s.nick}</b></td>
              <td><span class="nivel-badge badge-${s.nivel||'bronce'}">${nv?.emoji||''} ${nv?.nombre||'Bronce'}</span></td>
              <td>${nv?.streamer||20}%</td>
              <td class="gold-text">${usd(s.ingresos+s.ag+s.master)}</td>
              <td>${usd(s.master)}</td>
              <td class="green">${usd(s.ingresos)}</td>
            </tr>`;
          }).join('')}
        </tbody>
        <tfoot><tr>
          <td colspan="3">TOTALES AGENCIA</td>
          <td>${usd(Object.values(d.gAg[d.agencias[0].id]?.streamers||[]).reduce((a,s)=>a+s.ingresos+s.ag+s.master,0))}</td>
          <td>${usd(d.gAg[d.agencias[0].id]?.master_part||0)}</td>
          <td>${usd(d.gAg[d.agencias[0].id]?.str_ingresos||0)}</td>
        </tr></tfoot>
      </table>
    </div>` : ''}
  </div>

  <!-- STREAMERS DETALLE -->
  <div class="section-title">🎤 Detalle por Streamer</div>
  <table>
    <thead><tr><th>Streamer</th><th>Nivel</th><th>País</th><th>Frecuencia pago</th><th>Bruto ⭐</th><th>Su parte</th><th>Agencia</th><th>AURA</th><th>USD est.</th><th>Tx</th></tr></thead>
    <tbody>
      ${d.streamers.sort((a,b)=>(d.gStr[b.id]?.bruto||0)-(d.gStr[a.id]?.bruto||0)).map(s=>{
        const g=d.gStr[s.id]||{bruto:0,str_part:0,ag_part:0,master_part:0,tx:0};
        const nv=window.getNivel?.(s.nivel||'bronce');
        return `<tr>
          <td><b>@${s.nick||s.nombre}</b></td>
          <td><span class="nivel-badge badge-${s.nivel||'bronce'}">${nv?.emoji||''} ${nv?.nombre||'Bronce'}</span></td>
          <td>${s.pais||'—'}</td>
          <td style="text-transform:capitalize">${s.frecuencia_pago||'mensual'}</td>
          <td class="gold-text">${fmt(g.bruto)}</td>
          <td class="green">${fmt(g.str_part)}</td>
          <td class="purple">${fmt(g.ag_part)}</td>
          <td class="gold-text">${fmt(g.master_part)}</td>
          <td>${usd(g.bruto)}</td>
          <td style="text-align:center">${g.tx}</td>
        </tr>`;
      }).join('')}
    </tbody>
    <tfoot><tr>
      <td colspan="4">TOTALES</td>
      <td>${fmt(d.totBruto)}</td>
      <td class="green">${fmt(d.totStr)}</td>
      <td>${fmt(d.totAg)}</td>
      <td>${fmt(d.totMaster)}</td>
      <td>${usd(d.totBruto)}</td>
      <td style="text-align:center">${d.hist.length}</td>
    </tr></tfoot>
  </table>

  <!-- RETIROS -->
  ${d.retirosP.length > 0 ? `
  <div class="section-title">💳 Retiros en el Período</div>
  <table>
    <thead><tr><th>Streamer</th><th>Método</th><th>Cuenta</th><th>Monto</th><th>Estado</th><th>Fecha</th></tr></thead>
    <tbody>
      ${d.retirosP.map(r=>`<tr>
        <td><b>@${r.nick||'—'}</b></td>
        <td>${r.metodo||'—'}</td>
        <td>${r.cuenta||'—'}</td>
        <td class="gold-text">${r.monto_usd?'$'+r.monto_usd+' USD':(r.monto||0)+'★'}</td>
        <td class="estado-${r.estado||'pendiente'}">${(r.estado||'pendiente').toUpperCase()}</td>
        <td>${r.createdAt?.toDate?.()?.toLocaleDateString?.('es')||'—'}</td>
      </tr>`).join('')}
    </tbody>
  </table>` : ''}

</div>

<!-- FOOTER -->
<div class="gold-bar"></div>
<div class="footer">
  <div class="footer-logo">
    <img src="data:image/png;base64,${AURA_LOGO_B64}" alt="AURA">
    <div class="footer-brand">AURA</div>
  </div>
  <div class="footer-notes">
    <div>• Todos los montos en USD · 200⭐ = $1.00 USD</div>
    <div>• Los porcentajes varían según nivel y acuerdos especiales</div>
    <div>• Documento generado automáticamente por el Sistema AURA</div>
  </div>
  <div class="footer-right">
    <div class="gen-by">Generado por</div>
    <div class="gen-name">@${d.masterNick}</div>
    <div class="gen-date">${new Date().toLocaleString('es',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'})}</div>
  </div>
</div>

<button class="print-btn" onclick="window.print()">🖨️ IMPRIMIR / GUARDAR PDF</button>

</body>
</html>`;

    const win = window.open('', '_blank');
    if (!win) { toast('Permite ventanas emergentes para imprimir','error'); return; }
    win.document.write(html);
    win.document.close();
    setTimeout(()=> win.print(), 800);
  };
};
